df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    active = df[
        (df['row_kind'] != 'cancelled') &
        (df['row_kind'] != 'cancel') &
        (df['Currency'] == 'USD') &
        (df['Weight'] > 0) &
        (df['Weight UOM'].notna()) &
        (df['Weight UOM'] != '')
    ].copy()

    modes = active.groupby('Mode').agg(
        total_charge=('Total Charge', 'sum'),
        total_weight=('Weight', 'sum')
    ).reset_index()
