    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Total Charge",
        "aggregation": "sum",
        "label": "total_freight_cost_usd",
        "results": [
            {"name": str(row['Mode']), "value": round(float(row['total_charge']), 4)}
            for _, row in modes_sorted.iterrows()
        ]
    })

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Weight",
        "aggregation": "sum",
        "label": "total_weight_lb",
        "results": [
            {"name": str(row['Mode']), "value": round(float(row['total_weight']), 4)}
            for _, row in modes_sorted.iterrows()
        ]
    })

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Weight",
        "aggregation": "count",
        "label": "shipment_count",
        "results": [
            {"name": str(row['Mode']), "value": int(active[active['Mode'] == row['Mode']].shape[0])}
            for _, row in modes_sorted.iterrows()
        ]
    })

    result['assumptions'].append("cost_per_lb = sum(Total Charge) / sum(Weight) per Mode; cancelled and non-USD rows excluded; Weight > 0 and Weight UOM present required.")
    result['assumptions'].append("889 rows had Weight/Weight UOM type-coerced (unit converted); 5 rows with unknown unit sentinel-nulled and excluded via Weight > 0 filter.")
    result['assumptions'].append("73 cancelled rows and 87 non-USD rows excluded from all cost_per_lb calculations.")

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

